package com.xpe.mobile.preview;

import com.xpe.mobile.model.*;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.Assert.*;

/** Values generated by the pinned upstream Rust tween and speed_segment_tween functions. */
public class PrprScalarOracleTest {
    @Test public void matchesUpstreamScalarCorpus() throws Exception {
        Map<String, Double> worst = new TreeMap<>();
        Map<String, Integer> baselinePass = new TreeMap<>(), totals = new TreeMap<>();
        List<String> failures = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                getClass().getResourceAsStream("/prpr/scalar-oracle.csv"), StandardCharsets.UTF_8))) {
            reader.readLine();
            String row;
            while ((row = reader.readLine()) != null) {
                String[] cells = row.split(",");
                String kind = cells[0]; int easing = Integer.parseInt(cells[1]);
                double left = Double.parseDouble(cells[2]), right = Double.parseDouble(cells[3]);
                double x = Double.parseDouble(cells[4]), expected = Double.parseDouble(cells[5]);
                double actual, baseline;
                if (kind.equals("easing")) {
                    actual = PrprEvents.progress(x, easing, left, right, false, new double[4]);
                    baseline = Easing.applyWindowed(easing, x, left, right);
                }
                else {
                    ChartDocument chart = new ChartDocument(); chart.rpeVersion = kind.equals("modern") ? 170 : 160;
                    BpmChange bpm = new BpmChange(); bpm.bpm = 120; chart.bpmChanges.add(bpm);
                    JudgeLine line = new JudgeLine(); line.layer(0).events(EventType.SPEED).clear();
                    line.layer(0).events(EventType.SPEED).add(LineEvent.fromJson(EventType.SPEED,
                            new JSONObject().put("start",2).put("end",8).put("startTime",new JSONArray("[0,0,1]"))
                            .put("endTime",new JSONArray("[2,0,1]")).put("easingType",easing)
                            .put("easingLeft",left).put("easingRight",right)));
                    actual = new PrprSpeed(chart,line,4,true,new PrprTime(chart)).distanceAt(2*x) / (100 / .83175);
                    baseline = line.layer(0).events(EventType.SPEED).get(0).integratedRenderSpeed(0, 2*x, chart.rpeVersion, true) / 2;
                }
                totals.merge(kind, 1, Integer::sum);
                if (Math.abs(baseline - expected) <= .0002 + Math.abs(expected) * 2e-7) baselinePass.merge(kind, 1, Integer::sum);
                double error = Math.abs(expected - actual);
                worst.merge(kind,error,Math::max);
                if (!(error <= .0002 + Math.abs(expected) * 2e-7)) failures.add(row+" actual="+actual);
            }
        }
        System.out.println("Upstream scalar oracle maximum absolute errors: "+worst);
        System.out.println("Original 1.0.4 scalar matches: "+baselinePass+" / "+totals);
        assertTrue(failures.size()+" mismatches: "+failures.subList(0,Math.min(20,failures.size())), failures.isEmpty());
    }
}
